  ('00000015-0000-4000-8000-000000000004', '00000001-0000-4000-8000-0000000000c8', 'whatsapp', 'reschedule_proposed', '{"time":"06:40","ref":"SC-6B65VV","link":"/a/SC-6B65VV"}'::jsonb, 'Your doctor has proposed a new time 06:40 IST today for booking SC-6B65VV. Please respond: /a/SC-6B65VV', '/a/SC-6B65VV', '+91 98•••••001', 'sent', 'wamid.demo3', null, '2026-11-03T03:20:00.000Z'),
  ('00000015-0000-4000-8000-000000000005', '00000001-0000-4000-8000-0000000000c8', 'whatsapp', 'prescription_ready', '{"ref":"SC-38BSVH","link":"/a/SC-38BSVH"}'::jsonb, 'Your consultation summary for SC-38BSVH is ready. View it securely in the app: /a/SC-38BSVH', '/a/SC-38BSVH', '+91 98•••••001', 'read', 'wamid.demo4', '2026-10-29T04:15:00.000Z', '2026-10-29T04:10:00.000Z'),
  ('00000015-0000-4000-8000-000000000006', '00000001-0000-4000-8000-000000000064', 'whatsapp', 'doctor_new_booking', '{"date":"2026-11-03","time":"03:48","ref":"SC-XGXYTK","link":"/a/SC-XGXYTK"}'::jsonb, 'New teleconsultation booked for 2026-11-03 at 03:48 IST (ref SC-XGXYTK). Open: /a/SC-XGXYTK', '/a/SC-XGXYTK', '+91 98•••••001', 'read', 'wamid.demo5', '2026-11-01T03:45:00.000Z', '2026-11-01T03:40:00.000Z');
